def longestSub(ARRAY): 			
    ARRAY_LENGTH = len(ARRAY)
    if(ARRAY_LENGTH <= 1):  	
        return ARRAY
    PIVOT=ARRAY[0]
    isFound=False
    i=1
    LONGEST_SUB=[]
    while(not isFound and i<ARRAY_LENGTH):
        if (ARRAY[i] < PIVOT):
            isFound=True
            TEMPORARY_ARRAY = [ element for element in ARRAY[i:] if element >= ARRAY[i] ]
            TEMPORARY_ARRAY = longestSub(TEMPORARY_ARRAY)
            if ( len(TEMPORARY_ARRAY) > len(LONGEST_SUB) ):
                LONGEST_SUB = TEMPORARY_ARRAY
        else:
            i+=1
    TEMPORARY_ARRAY = [ element for element in ARRAY[1:] if element >= PIVOT ]
    TEMPORARY_ARRAY = [PIVOT] + longestSub(TEMPORARY_ARRAY)
    if ( len(TEMPORARY_ARRAY) > len(LONGEST_SUB) ):
        return TEMPORARY_ARRAY
    else:
        return LONGEST_SUB

def _alpha_grid(
    X,
    y,
    Xy=None,
    l1_ratio=1.0,
    fit_intercept=True,
    eps=1e-3,
    n_alphas=100,
    copy_X=True,
):
    if l1_ratio == 0:
        raise ValueError(
            "Automatic alpha grid generation is not supported for"
            " l1_ratio=0. Please supply a grid by providing "
            "your estimator with the appropriate `alphas=` "
            "argument."
        )
    n_samples = len(y)
    sparse_center = False
    if Xy is None:
        X_sparse = sparse.isspmatrix(X)
        sparse_center = X_sparse and fit_intercept
        X = check_array(
            X, accept_sparse="csc", copy=(copy_X and fit_intercept and not X_sparse)
        )
        if not X_sparse:
            X, y, _, _, _ = _preprocess_data(X, y, fit_intercept, copy=False)
        Xy = safe_sparse_dot(X.T, y, dense_output=True)
        if sparse_center:
            _, _, X_offset, _, X_scale = _preprocess_data(X, y, fit_intercept)
            mean_dot = X_offset * np.sum(y)
    if Xy.ndim == 1:
        Xy = Xy[:, np.newaxis]
    if sparse_center:
        if fit_intercept:
            Xy -= mean_dot[:, np.newaxis]
    alpha_max = np.sqrt(np.sum(Xy**2, axis=1)).max() / (n_samples * l1_ratio)
    if alpha_max <= np.finfo(float).resolution:
        alphas = np.empty(n_alphas)
        alphas.fill(np.finfo(float).resolution)
        return alphas
    return np.geomspace(alpha_max, alpha_max * eps, num=n_alphas)

